  const status = setupStatus ?? (await getSetupStatus());

  if (!status.appReady) {
    return null;
  }

  const requestHeaders = await headers();

  if (status.authMode === "local-dev") {
    return PASSWORD_VIEWER;
  }

  if (status.authMode === "password") {
    if (!getPasswordSessionFromHeaders(requestHeaders)) {
      console.warn("password session missing");
      return null;
    }
    return PASSWORD_VIEWER;
  }

  if (status.authMode !== "vercel") {
    return null;
  }

  try {
    const session = await auth.api.getSession({
      headers: requestHeaders,
    });

    if (!session?.user) {
      return null;
    }

    return {
      email: session.user.email,
      id: session.user.id,
      image: session.user.image ?? null,
      name: session.user.name,
    };
  } catch {
    return null;
  }
}
